package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;import com.yeyamo_mobile.api.notification_service.domain.*;
@Entity@Table(name="notification_deliveries")public class DeliveryEntity{@Id UUID id;@Column(name="notification_id",nullable=false)UUID notificationId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)NotificationChannel channel;@Column(length=500)String destination;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)DeliveryStatus status;@Column(nullable=false)int attempts;@Column(name="next_attempt_at")Instant nextAttemptAt;@Column(name="delivered_at")Instant deliveredAt;@Column(name="last_error",length=1000)String lastError;@Version long version;}
